"    let pointsEarnedOnBill = 0;
    if (customerPhone) {
      if (order.points_earned !== undefined && order.points_earned !== null) {
        pointsEarnedOnBill = order.points_earned;
      } else {
        if (getLoyaltySetting('loyalty_enabled', true)) {
          const threshold = parseFloat(getLoyaltySetting('loyalty_bill_amount_threshold', 100));
          const pointsAwarded = parseFloat(getLoyaltySetting('loyalty_points_earned', 1));
          const ratio = pointsAwarded / threshold;
          const targetAmount = parseFloat(order.total_price || totalAmount || subtotal || 0);
          pointsEarnedOnBill = targetAmount >= threshold ? Math.floor(targetAmount * ratio) : 0;
        } else {
          pointsEarnedOnBill = 0;
        }
      }
    }

    const fullPhoneKey = customerPhone ? (customerPhone.startsWith('+') ? customerPhone : customerCountryCode + customerPhone) : '';
    const rawPhoneKey = customerPhone ? (customerPhone.startsWith('+') ? customerPhone.substring(customerCountryCode.length) : customerPhone) : '';
    const isSavedCustomer = !!(customerPhone && (customerDb[fullPhoneKey] || customerDb[customerPhone] || customerDb[rawPhoneKey]));"

